#include <stdio.h>
#include <time.h>
#include <unistd.h>

static long ns(struct timespec a, struct timespec b) {
    return (b.tv_sec - a.tv_sec) * 1000000000L + (b.tv_nsec - a.tv_nsec);
}

int main(int argc, char **argv) {
    const long n = 2000000;
    struct timespec t0, t1, ts;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (long i = 0; i < n; i++) {
        if (argc > 1) getppid();                       /* a real system call */
        else clock_gettime(CLOCK_MONOTONIC, &ts);      /* served by the vDSO */
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    printf("%s: %ld ns per call\n", argc > 1 ? "getppid" : "clock_gettime", ns(t0, t1) / n);
    return 0;
}
